export type BrowserId = 'chrome' | 'edge' | 'firefox'

export type InstallMethod = 'store' | 'zip'

/** Stable public paths / store listings. Chrome zip regenerated by `pnpm prepare:downloads`. */
export const DOWNLOAD_URLS: Record<BrowserId, string> = {
  chrome: '/downloads/beatport-analyst-chrome.zip',
  edge: 'https://microsoftedge.microsoft.com/addons/detail/beatport-analyst/cofjamndkdofbfchbhfgmagndmihhapn',
  firefox: 'https://addons.mozilla.org/en-US/firefox/addon/beatport-analyst/'
}

export const BROWSERS: ReadonlyArray<{
  id: BrowserId
  label: string
  shortLabel: string
  method: InstallMethod
}> = [
  { id: 'chrome', label: 'Chrome', shortLabel: 'Chromium', method: 'zip' },
  { id: 'edge', label: 'Edge', shortLabel: 'Edge', method: 'store' },
  { id: 'firefox', label: 'Firefox', shortLabel: 'Firefox', method: 'store' }
]

export function getBrowser(id: BrowserId) {
  const browser = BROWSERS.find(entry => entry.id === id)
  if (!browser) throw new Error(`Unknown browser: ${id}`)
  return browser
}

/** Hero / download CTA label for the detected browser. */
export function getInstallCtaLabel(id: BrowserId): string {
  return getBrowser(id).method === 'store'
    ? 'Get extension from store'
    : 'Download the zip'
}

